import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { formatMoney } from "./money.mjs";
import { reconcile } from "./reconcile.mjs";
import { renderSummary } from "./summary.mjs";

function csvCell(value) {
	const text = String(value);
	return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

export function main(args) {
	const options = {};
	const required = ["orders", "events", "date", "out"];
	if (args.length % 2) throw new Error("参数必须以 --名称 值 成对提供");
	for (let i = 0; i < args.length; i += 2) {
		const key = args[i].slice(2);
		if (!args[i].startsWith("--") || !required.includes(key) || key in options || !args[i + 1]) throw new Error(`非法或重复参数: ${args[i]}`);
		options[key] = args[i + 1];
	}
	if (required.some(key => !options[key])) throw new Error("必填参数: --orders --events --date --out");
	const orders = JSON.parse(readFileSync(options.orders, "utf8"));
	const events = JSON.parse(readFileSync(options.events, "utf8"));
	const report = reconcile(orders, events, { date: options.date });
	mkdirSync(options.out, { recursive: true });
	writeFileSync(join(options.out, `${options.date}.json`), `${JSON.stringify(report, null, 2)}\n`);
	const csv = ["order_id,amount,payment,refund,net,status,outstanding,overpaid"];
	for (const row of report.orders) {
		csv.push([row.id, formatMoney(row.amountCents), formatMoney(row.paymentCents), formatMoney(row.refundCents), formatMoney(row.netCents), row.status, formatMoney(row.outstandingCents), formatMoney(row.overpaidCents)].map(csvCell).join(","));
	}
	writeFileSync(join(options.out, `${options.date}.csv`), `${csv.join("\n")}\n`);
	writeFileSync(join(options.out, "summary.md"), renderSummary(report));
	return report;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
	try {
		const report = main(process.argv.slice(2));
		console.log(JSON.stringify({ date: report.date, totals: report.totals }));
	} catch (error) {
		console.error(error.message);
		process.exitCode = 1;
	}
}

