	const end = start + 86400000;
	const allOrders = new Map();
	const selected = new Map();
	for (const order of orders) {
		if (allOrders.has(order.id)) throw new TypeError(`订单 ID 重复: ${order.id}`);
		allOrders.set(order.id, order);
		const created = timestamp(order.createdAt);
		if (created >= start && created < end) selected.set(order.id, {
			id: order.id, amountCents: toCents(order.amount), paymentCents: 0, refundCents: 0, feeCents: 0,
		});
	}
	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	// 必须先完整扫描所有版本，不能在发现冲突之前把首条入账。
	for (const { first: event, count, conflict } of groupEvents(events).values()) {
		const issue = (code) => issues.push({ eventId: event.eventId, orderId: event.orderId, code });
		if (conflict) { issue("conflicting_duplicate"); continue; }
		ignored.duplicates += count - 1;
		if (event.state !== "succeeded" || !["payment", "refund"].includes(event.kind)) { ignored.notSucceeded++; continue; }
		if (timestamp(event.occurredAt) >= end) { ignored.afterCutoff++; continue; }
		if (!allOrders.has(event.orderId)) { issue("orphan_event"); continue; }
		if (!selected.has(event.orderId)) { ignored.outsideOrderDate++; continue; }
		let cents;
		try { cents = toCents(event.amount); } catch { issue("invalid_amount"); continue; }
		const row = selected.get(event.orderId);
		const key = event.kind === "payment" ? "paymentCents" : "refundCents";
		row[key] = addCents(row[key], cents);
		if (event.kind === "payment") row.feeCents = addCents(row.feeCents, paymentFee(cents, feeBps));
	}
