import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync, mkdtempSync, rmSync } from "node:fs";
import { join } from "node:path";
import { reconcile } from "../src/reconcile.mjs";
import { paymentFee } from "../src/fees.mjs";
import { main } from "../src/cli.mjs";

const date = "2026-10-20";
const orders = [{ id: "a", amount: "10", createdAt: "2026-10-20T00:00:00+08:00" }];
const event = (eventId, changes = {}) => ({ eventId, orderId: "a", amount: "10", kind: "payment", state: "succeeded", occurredAt: "2026-10-20T01:00:00+08:00", ...changes });
const run = (events, feeBps = 60) => reconcile(orders, events, { date, feeBps });
const load = name => JSON.parse(readFileSync(new URL(`../data/${name}.json`, import.meta.url), "utf8"));
const sortedIssues = report => [...report.issues].sort((a,b) => a.eventId.localeCompare(b.eventId));

test("conflicts in each of the five business fields quarantine the whole ID before other filters", () => {
	for (const change of [{ orderId: "missing" }, { amount: "1" }, { kind: "refund" }, { state: "failed" }, { occurredAt: "2026-10-21T00:00:00Z" }]) {
		const first = event("conflict");
		const second = event("conflict", change);
		for (const group of [[first, first, second, second], [second, first, second, first]]) {
			const r = run(group);
			assert.equal(r.totals.paymentCents, 0);
			assert.equal(r.totals.refundCents, 0);
			assert.equal(r.totals.feeCents, 0);
			assert.equal(r.issues.length, 1);
			assert.equal(r.issues[0].eventId, "conflict");
			assert.equal(r.issues[0].code, "conflicting_duplicate");
			assert.deepEqual(r.ignored, { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 });
		}
	}
});

test("receivedAt is irrelevant to equality, duplicates count normally and independent IDs survive", () => {
	const r = run([event("same", { receivedAt: "2026-10-21T01:00:00Z" }), event("same", { receivedAt: "2026-10-22T01:00:00Z" }), event("same"), event("bad", { amount: "1" }), event("bad", { amount: "2" }), event("independent")]);
	assert.equal(r.ignored.duplicates, 2);
	assert.equal(r.issues.length, 1);
	assert.equal(r.totals.paymentCents, 2000);
	assert.equal(r.totals.feeCents, 12);
});

test("fees round half up per payment, not on order/day totals; refund does not reverse fees", () => {
	assert.equal(paymentFee(249, 60), 1);
	assert.equal(paymentFee(250, 60), 2);
	assert.equal(paymentFee(251, 60), 2);
	assert.equal(paymentFee(19990, 60), 120);
	// 83 分 + 83 分：逐笔均不到半分，手续费为 0，不能汇总后收 1 分。
	const r = run([event("p1", { amount: "0.83" }), event("p2", { amount: "0.83" }), event("half", { amount: "2.50" }), event("refund", { kind: "refund", amount: "4.16" })]);
	assert.equal(r.totals.paymentCents, 416);
	assert.equal(r.totals.refundCents, 416);
	assert.equal(r.totals.netCents, 0);
	assert.equal(r.totals.feeCents, 2);
	assert.equal(r.totals.settlementCents, -2);
	const zero = run([event("zero", { amount: "0" })]);
	assert.equal(zero.totals.feeCents, 0);
});

test("only validated successful payments incur fees; after-cutoff and unknown order never do", () => {
	const valid = event("valid", { amount: "2.50" });
	const r = run([valid, { ...valid, receivedAt: "2026-10-22T01:00:00Z" }, event("failed", { state: "failed" }), event("pending", { state: "pending" }), event("late", { occurredAt: "2026-10-20T16:00:00Z" }), event("missing", { orderId: "missing" }), event("invalid", { amount: "1.001" }), event("c", { amount: "100" }), event("c", { amount: "200" }), event("refund", { kind: "refund", amount: "1.00" })]);
	assert.equal(r.totals.paymentCents, 250);
	assert.equal(r.totals.refundCents, 100);
	assert.equal(r.totals.netCents, 150);
	assert.equal(r.totals.feeCents, 2);
	assert.equal(r.totals.settlementCents, 148);
	assert.deepEqual(r.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 1, outsideOrderDate: 0 });
	assert.equal(r.issues.length, 3);
});

test("fee validation and safe integer operations", () => {
	for (const bad of [-1, 0.6, NaN, Infinity, "60", Number.MAX_SAFE_INTEGER + 1]) assert.throws(() => run([], bad));
	assert.equal(paymentFee(Number.MAX_SAFE_INTEGER, 60), Number((BigInt(Number.MAX_SAFE_INTEGER) * 60n + 5000n) / 10000n));
	assert.throws(() => paymentFee(Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER));
	assert.throws(() => run([event("p", { amount: "90071992547409.91" })], Number.MAX_SAFE_INTEGER));
});

test("updated file exact totals, all order fees, issues, counters and zero-rate compatibility", () => {
	const r = reconcile(load("orders"), load("events-update"), { date, feeBps: 60 });
	assert.deepEqual(r.totals, { orderCount: 7, orderCents: 55520, paymentCents: 55520, refundCents: 6990, netCents: 48530, outstandingCents: 0, overpaidCents: 0, feeCents: 333, settlementCents: 48197 });
	assert.deepEqual(r.orders.map(r => [r.id, r.paymentCents, r.refundCents, r.feeCents, r.settlementCents, r.status]), [
		["O1001", 19990, 4990, 120, 14880, "refunded"], ["O1002", 8000, 0, 48, 7952, "paid"], ["O1003", 5000, 2000, 30, 2970, "refunded"], ["O1004", 12000, 0, 72, 11928, "paid"], ["O1005", 3500, 0, 21, 3479, "paid"], ["O1006", 30, 0, 0, 30, "paid"], ["O1007", 7000, 0, 42, 6958, "paid"],
	]);
	assert.deepEqual(sortedIssues(r), [ { eventId: "e05", orderId: "O1004", code: "conflicting_duplicate" }, { eventId: "e09", orderId: "O9999", code: "orphan_event" }, { eventId: "e13", orderId: "O1005", code: "invalid_amount" } ]);
	assert.deepEqual(r.ignored, { duplicates: 1, notSucceeded: 2, afterCutoff: 2, outsideOrderDate: 0 });
	for (const row of r.orders) {
		assert.equal(row.settlementCents, row.netCents - row.feeCents);
		assert.equal(row.outstandingCents, 0);
	}
	const reversed = reconcile(load("orders").reverse(), load("events-update").reverse(), { date, feeBps: 60 });
	assert.deepEqual(reversed.orders, r.orders);
	assert.deepEqual(reversed.totals, r.totals);
	assert.deepEqual(sortedIssues(reversed), sortedIssues(r));
	assert.deepEqual(reversed.ignored, r.ignored);
	const noFee = reconcile(load("orders"), load("events-update"), { date });
	assert.equal(noFee.totals.feeCents, 0);
	assert.equal(noFee.totals.settlementCents, 48530);
	assert.equal(noFee.totals.netCents, r.totals.netCents);
	const before = reconcile(load("orders"), load("events"), { date });
	assert.equal(r.totals.paymentCents - before.totals.paymentCents, 12500);
	assert.equal(r.totals.refundCents - before.totals.refundCents, 4990);
	assert.equal(r.totals.settlementCents - before.totals.settlementCents, 7177);
});

