		for (const row of csv.slice(1)) assert.ok(row.split(",").filter((_,i) => ![0,5].includes(i)).every(n => /^-?\d+\.\d{2}$/.test(n)));
		const summary = readFileSync(join(out, "summary.md"), "utf8");
		for (const text of ["555.20", "69.90", "3.33", "481.97", "71.77", "e05", "e09", "e13", "e20", "receivedAt", "有矛盾，需要核对渠道账单"]) assert.ok(summary.includes(text), text);
	} finally { rmSync(temp, { recursive: true, force: true }); }
});

