		[{ eventId: "demo-pay", orderId: "demo", kind: "payment", state: "succeeded", amount: "10.00", occurredAt: "2026-10-20T02:00:00Z" }],
		{ date: "2026-10-20" },
	);
	assert.equal(report.totals.netCents, 1000);
