import { toCents } from "./money.mjs";

function toLocalDateString(isoString) {
	const date = new Date(isoString);
	if (!Number.isFinite(date.getTime())) {
		return null;
	}
	const parts = new Intl.DateTimeFormat("en-CA", {
		timeZone: "Asia/Shanghai",
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
	}).formatToParts(date);
	const values = Object.fromEntries(
		parts
			.filter((part) => part.type !== "literal")
			.map((part) => [part.type, part.value]),
	);
	if (!values.year || !values.month || !values.day) {
		return null;
	}
	return `${values.year}-${values.month}-${values.day}`;
}

export function reconcile(orders, events, { date }) {
	const allOrderMap = new Map();
	for (const order of orders) {
		allOrderMap.set(order.id, order);
	}

	const rowsById = new Map();
	const dateCutoff = new Date(`${date}T15:59:59.999Z`).getTime();

	for (const order of orders) {
		if (toLocalDateString(order.createdAt) !== date) {
			continue;
		}
		rowsById.set(order.id, {
			id: order.id,
			amountCents: toCents(order.amount),
			paymentCents: 0,
			refundCents: 0,
			netCents: 0,
			outstandingCents: 0,
			overpaidCents: 0,
			status: "unpaid",
		});
	}

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const seenEventIds = new Set();

	for (const event of events) {
		if (seenEventIds.has(event.eventId)) {
			ignored.duplicates += 1;
			continue;
		}
		seenEventIds.add(event.eventId);

		if (event.state !== "succeeded") {
			ignored.notSucceeded += 1;
			continue;
		}

		const occurredAt = new Date(event.occurredAt);
		if (!Number.isFinite(occurredAt.getTime()) || occurredAt.getTime() > dateCutoff) {
			ignored.afterCutoff += 1;
			continue;
		}

		const order = allOrderMap.get(event.orderId);
		if (!order) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "orphan_event" });
			continue;
		}

		if (toLocalDateString(order.createdAt) !== date) {
			ignored.outsideOrderDate += 1;
			continue;
		}

		const row = rowsById.get(event.orderId);
		if (!row) {
			continue;
		}

		let amountCents;
		try {
			amountCents = toCents(event.amount);
		} catch {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "invalid_amount" });
			continue;
		}

		if (event.kind === "payment") {
			row.paymentCents += amountCents;
		} else if (event.kind === "refund") {
			row.refundCents += amountCents;
		}
	}

	const rows = [...rowsById.values()]
		.map((row) => {
			row.netCents = row.paymentCents - row.refundCents;
			row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
			row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
			if (row.refundCents > 0) {
				row.status = "refunded";
			} else if (row.paymentCents === 0) {
				row.status = "unpaid";
			} else if (row.paymentCents < row.amountCents) {
				row.status = "partial";
			} else if (row.paymentCents > row.amountCents) {
				row.status = "overpaid";
			} else {
				row.status = "paid";
			}
			return row;
		})
		.sort((a, b) => a.id.localeCompare(b.id, "en", { numeric: true }));

	const totals = {
		orderCount: rows.length,
		orderCents: rows.reduce((sum, row) => sum + row.amountCents, 0),
		paymentCents: rows.reduce((sum, row) => sum + row.paymentCents, 0),
		refundCents: rows.reduce((sum, row) => sum + row.refundCents, 0),
		netCents: rows.reduce((sum, row) => sum + row.netCents, 0),
		outstandingCents: rows.reduce((sum, row) => sum + row.outstandingCents, 0),
		overpaidCents: rows.reduce((sum, row) => sum + row.overpaidCents, 0),
	};

	return {
		date,
		timezone: "Asia/Shanghai",
		totals,
		orders: rows,
		ignored,
		issues,
	};
}

