const AMOUNT_PATTERN = /^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/;

export function toCents(value) {
	if (typeof value !== "string" || !AMOUNT_PATTERN.test(value)) {
		return null;
	}
	const [whole, fraction = ""] = value.split(".");
	const cents = BigInt(whole) * 100n + BigInt(fraction.padEnd(2, "0"));
	if (cents > BigInt(Number.MAX_SAFE_INTEGER)) {
		return null;
	}
	return Number(cents);
}

export function formatMoney(cents) {
	const negative = cents < 0;
	const absolute = Math.abs(cents);
	const whole = Math.floor(absolute / 100);
	const fraction = String(absolute % 100).padStart(2, "0");
	return `${negative ? "-" : ""}${whole}.${fraction}`;
}

import { formatMoney, toCents } from "./money.mjs";

const BEIJING_OFFSET_MS = 8 * 60 * 60 * 1000;
const DAY_MS = 24 * 60 * 60 * 1000;

const STATUS_LABEL = {
	unpaid: "未付款",
	partial: "部分付款",
	overpaid: "多付款",
	paid: "已收齐",
	refunded: "已退款",
};

const ISSUE_LABEL = {
	orphan_event: "找不到订单",
	invalid_amount: "金额不合法",
};

export function beijingDayRange(date) {
	if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
		throw new Error(`invalid date: ${date}`);
	}
	const [year, month, day] = date.split("-").map(Number);
	const startUtc = Date.UTC(year, month - 1, day) - BEIJING_OFFSET_MS;
	return { startUtc, endUtc: startUtc + DAY_MS - 1 };
}

function parseInstant(value) {
	if (typeof value !== "string" || value.trim() === "") {
		return null;
	}
	const ms = Date.parse(value);
	return Number.isFinite(ms) ? ms : null;
}

function statusFor(row) {
	if (row.refundCents > 0) {
		return "refunded";
	}
	if (row.paymentCents === 0) {
		return "unpaid";
	}
	if (row.paymentCents < row.amountCents) {
		return "partial";
	}
	if (row.paymentCents > row.amountCents) {
		return "overpaid";
	}
	return "paid";
}

function yuan(cents) {
	return `${formatMoney(cents)} 元`;
}

export function reconcile(orders, events, { date }) {
	const { startUtc, endUtc } = beijingDayRange(date);
	const orderById = new Map();
	for (const order of orders) {
		if (!orderById.has(order.id)) {
			orderById.set(order.id, order);
		}
	}

	const rowsById = new Map();
	for (const order of orders) {
		if (rowsById.has(order.id)) {
			continue;
		}
		const createdMs = parseInstant(order.createdAt);
		if (createdMs === null || createdMs < startUtc || createdMs > endUtc) {
			continue;
		}
		const amountCents = toCents(order.amount);
		rowsById.set(order.id, {
			id: order.id,
			amountCents: amountCents ?? 0,
			paymentCents: 0,
			refundCents: 0,
			netCents: 0,
			outstandingCents: 0,
			overpaidCents: 0,
			status: "unpaid",
		});
	}

	const ignored = { duplicates: 0, notSucceeded: 0, afterCutoff: 0, outsideOrderDate: 0 };
	const issues = [];
	const seenEventIds = new Set();

	for (const event of events) {
		if (seenEventIds.has(event.eventId)) {
			ignored.duplicates += 1;
			continue;
		}
		seenEventIds.add(event.eventId);

		if (event.state !== "succeeded") {
			ignored.notSucceeded += 1;
			continue;
		}

		const occurredMs = parseInstant(event.occurredAt);
		if (occurredMs === null || occurredMs > endUtc) {
			ignored.afterCutoff += 1;
			continue;
		}

		const order = orderById.get(event.orderId);
		if (!order) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "orphan_event" });
			continue;
		}

		const createdMs = parseInstant(order.createdAt);
		if (createdMs === null || createdMs < startUtc || createdMs > endUtc) {
			ignored.outsideOrderDate += 1;
			continue;
		}

		const cents = toCents(event.amount);
		if (cents === null) {
			issues.push({ eventId: event.eventId, orderId: event.orderId, code: "invalid_amount" });
			continue;
		}

		const row = rowsById.get(event.orderId);
		if (!row) {
			continue;
		}
		if (event.kind === "payment") {
			row.paymentCents += cents;
		} else if (event.kind === "refund") {
			row.refundCents += cents;
		}
	}

	const rows = [...rowsById.values()].sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
	for (const row of rows) {
		row.netCents = row.paymentCents - row.refundCents;
		row.outstandingCents = Math.max(row.amountCents - row.paymentCents, 0);
		row.overpaidCents = Math.max(row.paymentCents - row.amountCents, 0);
		row.status = statusFor(row);
	}

	const totals = {
		orderCount: rows.length,
		orderCents: 0,
		paymentCents: 0,
		refundCents: 0,
		netCents: 0,
		outstandingCents: 0,
		overpaidCents: 0,
	};
	for (const row of rows) {
		totals.orderCents += row.amountCents;
		totals.paymentCents += row.paymentCents;
		totals.refundCents += row.refundCents;
		totals.netCents += row.netCents;
		totals.outstandingCents += row.outstandingCents;
		totals.overpaidCents += row.overpaidCents;
	}

	return {
		date,
		timezone: "Asia/Shanghai",
		totals,
		orders: rows,
		ignored,
		issues,
	};
}

export function renderCsv(report) {
	const lines = ["order_id,amount,payment,refund,net,status,outstanding,overpaid"];
	for (const row of report.orders) {
		lines.push([
			row.id,
			formatMoney(row.amountCents),
			formatMoney(row.paymentCents),
			formatMoney(row.refundCents),
			formatMoney(row.netCents),
			row.status,
			formatMoney(row.outstandingCents),
			formatMoney(row.overpaidCents),
		].join(","));
	}
	return `${lines.join("\n")}\n`;
}

export function renderSummary(report) {
	const totals = report.totals;
	const collect = report.orders.filter((order) => order.outstandingCents > 0);
	const overpaid = report.orders.filter((order) => order.overpaidCents > 0);
	const refunded = report.orders.filter((order) => order.status === "refunded");
	const lines = [
		`# ${report.date} 日结交接`,
		"",
		`统计口径：北京时间（${report.timezone}，UTC+08:00）。只看当天创建的订单，成功支付和退款按 occurredAt 计算，截止到当天 23:59:59.999。金额用整数分计算，再换算成两位小数的元。`,
		"",
		"## 合计",
		"",
		`- 收款：${yuan(totals.paymentCents)}（${totals.paymentCents} 分）`,
		`- 退款：${yuan(totals.refundCents)}（${totals.refundCents} 分）`,
		`- 净收款：${yuan(totals.netCents)}（${totals.netCents} 分）`,
		`- 订单数：${totals.orderCount}，订单金额 ${yuan(totals.orderCents)}`,
		`- 未收齐：${yuan(totals.outstandingCents)}。这是原订单还没付够的部分，退款不会再记成欠款。`,
		`- 多付款：${yuan(totals.overpaidCents)}`,
		"",
		"净收款 = 收款 - 退款。未收齐和已经退款分开列，不能互相抵消或混成一类。",
		"",
		"## 需要催款的订单",
		"",
	];

	if (collect.length === 0) {
		lines.push("没有未收齐的订单，不需要催款。");
	} else {
		lines.push("以下订单原金额还没收齐，需要催款。状态只是分类，脚本不会自动发催款。");
		for (const order of collect) {
			lines.push(`- ${order.id}：${STATUS_LABEL[order.status] ?? order.status}，订单 ${yuan(order.amountCents)}，已收 ${yuan(order.paymentCents)}，未收齐 ${yuan(order.outstandingCents)}。`);
		}
	}

	lines.push("", "## 需要处理多付款的订单", "");
	if (overpaid.length === 0) {
		lines.push("没有多付款的订单。");
	} else {
		lines.push("以下订单成功支付超过订单金额，需要处理多付款。脚本不会自动退款。");
		for (const order of overpaid) {
			lines.push(`- ${order.id}：${STATUS_LABEL[order.status] ?? order.status}，订单 ${yuan(order.amountCents)}，已收 ${yuan(order.paymentCents)}，多付 ${yuan(order.overpaidCents)}。`);
		}
	}

	lines.push("", "## 已经退款的订单", "");
	if (refunded.length === 0) {
		lines.push("当天没有成功退款。");
	} else {
		lines.push("以下订单有成功退款，单独列出。退款不是欠款；未收齐仍只看订单金额减去成功支付。");
		for (const order of refunded) {
			lines.push(`- ${order.id}：已退款，收款 ${yuan(order.paymentCents)}，退款 ${yuan(order.refundCents)}，净额 ${yuan(order.netCents)}，未收齐 ${yuan(order.outstandingCents)}，多付 ${yuan(order.overpaidCents)}。`);
		}
	}

	lines.push("", "## 人工核查", "");
	if (report.issues.length === 0) {
		lines.push("没有需要人工核查的通知。");
	} else {
		lines.push("以下通知没有计入收款、退款、净收款，也不能悄悄并进总额，需要人工核查：");
		for (const issue of report.issues) {
			const reason = ISSUE_LABEL[issue.code] ?? issue.code;
			lines.push(`- 通知 ${issue.eventId}，订单 ${issue.orderId}：${reason}（${issue.code}）。`);
		}
	}

	lines.push(
		"",
		"## 已执行的检查",
		"",
		`- 重复通知：${report.ignored.duplicates} 条完全重复的 eventId 只保留第一次，没有重复入账。`,
		`- 非成功状态：${report.ignored.notSucceeded} 条失败或等待中的通知未入账。`,
		`- 截止时间：${report.ignored.afterCutoff} 条晚于当天 23:59:59.999 的通知暂不计入。`,
		`- 其他日期订单：${report.ignored.outsideOrderDate} 条通知属于其他日期的订单，没有当成找不到订单，也没有计入当天合计。`,
		"- 金额校验：拒绝负数、空字符串、科学计数法、NaN 和多于两位小数的金额；有效金额按整数分相加，避免小数误差。",
		"- 日期按北京时间判断订单是否在当天创建，通知按 occurredAt 而不是接收时间判断。",
		"- 订单按 ID 排序。JSON 金额为整数分，CSV 金额为固定两位小数的元。",
		"- 判断顺序为：重复通知、非成功状态、晚于截止、找不到订单、订单不属于当天、金额是否合法。",
		"",
		"## 剩余限制",
		"",
		"- 只根据本次给出的订单和通知文件计算，没有连接支付渠道核对原始账单。",
		"- 人工核查只标明原因，不代替财务决定该不该入账。",
		"- 未收齐和多付款只是报表分类，不会自动催款或退款。",
		"- 晚于截止时间的通知留到后续日期处理，本次不补记。",
		"",
	);
	return lines.join("\n");
}

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { reconcile, renderCsv, renderSummary } from "./reconcile.mjs";

const args = process.argv.slice(2);
const options = Object.fromEntries(Array.from({ length: args.length / 2 }, (_, index) => [args[index * 2].slice(2), args[index * 2 + 1]]));
const orders = JSON.parse(readFileSync(options.orders, "utf8"));
const events = JSON.parse(readFileSync(options.events, "utf8"));
const report = reconcile(orders, events, { date: options.date });
mkdirSync(options.out, { recursive: true });
writeFileSync(join(options.out, `${options.date}.json`), `${JSON.stringify(report, null, 2)}\n`);
writeFileSync(join(options.out, `${options.date}.csv`), renderCsv(report));
writeFileSync(join(options.out, "summary.md"), renderSummary(report));
console.log(JSON.stringify({ json: `${options.out}/${options.date}.json`, csv: `${options.out}/${options.date}.csv` }));

