test("money parses decimal strings as integer cents and rejects invalid amounts", () => {
	assert.equal(toCents("199.90"), 19990);
	assert.equal(toCents("0.10"), 10);
	assert.equal(toCents("0.20"), 20);
	assert.equal(toCents("0.29"), 29);
	assert.equal(toCents("1.15"), 115);
	assert.equal(toCents("10"), 1000);
	assert.equal(toCents("10.5"), 1050);
	assert.equal(toCents("0"), 0);
	assert.equal(toCents("0.00"), 0);
	for (const invalid of ["-5.00", "", "1e2", "1E+2", "NaN", "1.234", "10.000", "Infinity", "+10.00", " 10.00", "10.", ".5", "10.10.1"]) {
		assert.equal(toCents(invalid), null, invalid);
	}
	assert.equal(toCents(10), null);
	assert.equal(toCents(null), null);
	assert.equal(formatMoney(19990), "199.90");
	assert.equal(formatMoney(10), "0.10");
	assert.equal(formatMoney(0), "0.00");
	assert.equal(formatMoney(-500), "-5.00");
	assert.equal(formatMoney(29), "0.29");
});

