test("duplicates, failed or pending events, orphans and invalid amounts stay out of totals", () => {
	const report = reconcile(
		[
			{ id: "A", amount: "100.00", createdAt: "2026-10-20T01:00:00Z" },
			{ id: "B", amount: "80.00", createdAt: "2026-10-18T01:00:00Z" },
		],
		[
			{ eventId: "dup", orderId: "A", kind: "payment", state: "failed", amount: "bad", occurredAt: "2026-10-20T01:00:00Z" },
			{ eventId: "dup", orderId: "A", kind: "payment", state: "succeeded", amount: "40.00", occurredAt: "2026-10-20T01:00:00Z" },
			{ eventId: "fail", orderId: "MISSING", kind: "payment", state: "pending", amount: "-1", occurredAt: "2026-10-21T00:00:00Z" },
			{ eventId: "late", orderId: "MISSING", kind: "payment", state: "succeeded", amount: "1.00", occurredAt: "2026-10-20T16:00:00Z" },
			{ eventId: "orphan", orderId: "MISSING", kind: "payment", state: "succeeded", amount: "-2.00", occurredAt: "2026-10-20T02:00:00Z" },
			{ eventId: "other", orderId: "B", kind: "refund", state: "succeeded", amount: "1.234", occurredAt: "2026-10-20T02:00:00Z" },
			{ eventId: "bad", orderId: "A", kind: "refund", state: "succeeded", amount: "1e2", occurredAt: "2026-10-20T02:00:00Z" },
			{ eventId: "empty", orderId: "A", kind: "payment", state: "succeeded", amount: "", occurredAt: "2026-10-20T02:10:00Z" },
			{ eventId: "nan", orderId: "A", kind: "payment", state: "succeeded", amount: "NaN", occurredAt: "2026-10-20T02:20:00Z" },
			{ eventId: "ok", orderId: "A", kind: "payment", state: "succeeded", amount: "40.00", occurredAt: "2026-10-20T03:00:00Z" },
			{ eventId: "ok", orderId: "A", kind: "payment", state: "succeeded", amount: "40.00", occurredAt: "2026-10-20T03:00:00Z", receivedAt: "2026-10-21T00:00:00Z" },
		],
		{ date: "2026-10-20" },
	);
	assert.equal(report.ignored.duplicates, 2);
	assert.equal(report.ignored.notSucceeded, 1);
	assert.equal(report.ignored.afterCutoff, 1);
	assert.equal(report.ignored.outsideOrderDate, 1);
	assert.deepEqual(report.issues, [
		{ eventId: "orphan", orderId: "MISSING", code: "orphan_event" },
		{ eventId: "bad", orderId: "A", code: "invalid_amount" },
		{ eventId: "empty", orderId: "A", code: "invalid_amount" },
		{ eventId: "nan", orderId: "A", code: "invalid_amount" },
	]);
	assert.equal(report.orders.length, 1);
	assert.equal(report.orders[0].paymentCents, 4000);
	assert.equal(report.orders[0].refundCents, 0);
	assert.equal(report.totals.paymentCents, 4000);
	assert.equal(report.totals.netCents, 4000);
});

